mapper.select:
/* selectEntscPreconUnityReprts 입교현황통합보고서 - Lee SangHoon */ WITH TMP000 AS ( SELECT
T.TRPR_INFO_NO -- 대상자정보번호 , T.APLY_RCPT_SN -- 신청접수일련번호 , T5.APLY_RCPT_SRNG_SE_CD -- 신청접수심사구분코드 , T5.APLY_RCPT_SRNG_PRGRS_STTS_SE_CD -- 신청접수심사진행상태구분코드 , T6.TRMN_SE_CD -- 종결구분코드 , T6.TRMN_CS_SE_CD -- 종결사유구분코드
, T1.SXDC_SE_CD -- 성별구분코드 , T2.ACBG_SE_CD -- 학력구분코드 , T7.ACBG_SE_CD AS SCHULW_DSCNTC_ACBG_SE_CD -- 학업중단학력구분코드 , SUBSTR(T1.ZIP,0,2) AS ZIP -- 우편번호(시도) , T1.PBLAST_SE_CD -- 공적부조 , T1.FAM_SHAPE_SE_CD -- 가족형태구분코드 , T3.DSCSN_CONT -- 상담횟수 , T3.RPRS_MAAP_PROBM_SE_CD -- 대표주호소구분코드 , T3.SPCLA_PROBM_DRFSTF -- 특별문제유형여부 - 약물 , T3.SPCLA_PROBM_DRNKG -- 특별문제유형여부 - 음주 , T3.SPCLA_PROBM_GAMBLE -- 특별문제유형여부 - 도박 , T3.LGSLTN_PRTCTN_OBSERV -- 법률문제 - 보호관찰 , T3.LGSLTN_TRL -- 법률문제 - 재판진행 , T3.LGSLTN_SCHL_VIOLNC -- 법률문제 - 학교폭력 , T3.LGSLTN_POLC_EXMN -- 법률문제 - 경찰조사 , T4.LIVTGT_YN -- 동거여부 , T4.LVING_MNG_YN -- 생활관리여부
FROM AFA100 T /* 신청접수 */ JOIN SEA200 T1 /* 대상자정보 */ ON T1.TRPR_INFO_NO = T.TRPR_INFO_NO JOIN AFA150 T5 /* 신청접수심사상태정보이력 */ ON T5.TRPR_INFO_NO = T.TRPR_INFO_NO AND T5.APLY_RCPT_SN = T.APLY_RCPT_SN LEFT JOIN /* 학력상태 */ ( SELECT A.* , ROW_NUMBER() OVER(PARTITION BY A.TRPR_INFO_NO ORDER BY B.ADDTNG_MNG_VALUE1 DESC, A.MNG_SN DESC) AS ROW_NUMBER FROM SEA230 A /* 학력상태 */ JOIN SAC100 B /* 공통코드 값 */ ON B.CMMNS_CD_ID = 'ACBG_SE_CD' -- 학력구분코드 AND B.CMMNS_CD_VALUE = A.ACBG_SE_CD ) T2 ON T2.TRPR_INFO_NO = T.TRPR_INFO_NO AND T2.ROW_NUMBER = 1 LEFT JOIN /* 학업중단 */ ( SELECT A.* , ROW_NUMBER() OVER(PARTITION BY A.TRPR_INFO_NO ORDER BY A.MNG_SN DESC) AS ROW_NUMBER FROM SEA240 A /* 학업중단 */ ) T7 ON T7.TRPR_INFO_NO = T.TRPR_INFO_NO AND T7.ROW_NUMBER = 1 LEFT JOIN /* 대상자문제상태내역 */ ( SELECT A.TRPR_INFO_NO , A.APLY_RCPT_SN , A.DSCSN_CONT , A.RPRS_MAAP_PROBM_SE_CD , COUNT(CASE B.COMPNO_TYPE_SCLAS_SE_CD WHEN '020403' THEN 1 END) AS SPCLA_PROBM_DRFSTF , COUNT(CASE B.COMPNO_TYPE_SCLAS_SE_CD WHEN '020401' THEN 1 END) AS SPCLA_PROBM_DRNKG , COUNT(CASE B.COMPNO_TYPE_SCLAS_SE_CD WHEN '020402' THEN 1 END) AS SPCLA_PROBM_GAMBLE , COUNT(CASE B.COMPNO_TYPE_SCLAS_SE_CD WHEN '010203' THEN 1 END) AS LGSLTN_PRTCTN_OBSERV , COUNT(CASE B.COMPNO_TYPE_SCLAS_SE_CD WHEN '010204' THEN 1 END) AS LGSLTN_TRL , COUNT(CASE B.COMPNO_TYPE_SCLAS_SE_CD WHEN '010205' THEN 1 END) AS LGSLTN_SCHL_VIOLNC , COUNT(CASE B.COMPNO_TYPE_SCLAS_SE_CD WHEN '010202' THEN 1 END) AS LGSLTN_POLC_EXMN FROM AFA120 A /* 대상자문제상태내역 */ LEFT JOIN AFA131 B /* 복수선택유형상세 */ ON B.COMPNO_CHC_TYPE_MNG_NO = A.COMPNO_CHC_TYPE_MNG_NO
GROUP BY A.TRPR_INFO_NO, A.APLY_RCPT_SN, A.DSCSN_CONT, A.RPRS_MAAP_PROBM_SE_CD ) T3 ON T3.TRPR_INFO_NO = T.TRPR_INFO_NO AND T3.APLY_RCPT_SN = T.APLY_RCPT_SN LEFT JOIN /* 항목별응답내용 - 정성평가 */ ( SELECT A.TRPR_INFO_NO , A.APLY_RCPT_SN , C.LIVTGT_YN , C.LVING_MNG_YN FROM ( SELECT A1.* , ROW_NUMBER() OVER (PARTITION BY A1.QUSTNB_TMPT_MNG_NO, A1.TRPR_INFO_NO, A1.APLY_RCPT_SN ORDER BY A1.REG_YMD DESC, A1.MNG_SN DESC) AS ROW_NUMBER FROM SBB600 A1 /* 설문발송이력 */ JOIN SAC100 A2 /* 공통코드 값 */ ON A2.ADDTNG_MNG_VALUE1 = A1.QUSTNB_TMPT_MNG_NO AND A2.CMMNS_CD_ID = 'QUSTNB_KND_SE_CD' -- 설문지종류구분코드 AND A2.CMMNS_CD_VALUE = '006' -- 설문지종류:정성평가 WHERE A1.SRVY_ERA_SE_CD = '01' -- 설문시기:사전 ) A JOIN ( SELECT B1.* , ROW_NUMBER() OVER(PARTITION BY B1.QUSTNB_TMPT_MNG_NO, B1.QUSTNB_MNG_NO ORDER BY B1.RSPNS_DT DESC) AS ROW_NUMBER FROM SBB500 B1 /* 설문응답 */ ) B ON B.QUSTNB_TMPT_MNG_NO = A.QUSTNB_TMPT_MNG_NO AND B.QUSTNB_MNG_NO = A.QUSTNB_MNG_NO AND B.ROW_NUMBER = 1 JOIN ( SELECT * FROM ( SELECT C1.QUSTNB_TMPT_MNG_NO , C1.QESITM_SQNCE , C2.SRVY_RSPNS_MNG_NO , C2.QESITM_SINGL_RSPNS_VALUE FROM SBB010 C1 /* 설문지문항템플릿 */ JOIN SBB220 C2 /* 항목별응답내용 */ ON C2.QESITM_MNG_NO = C1.QESITM_MNG_NO ) PIVOT ( AVG(QESITM_SINGL_RSPNS_VALUE) FOR QESITM_SQNCE IN(7 AS LIVTGT_YN, 8 AS LVING_MNG_YN) ) ) C ON C.QUSTNB_TMPT_MNG_NO = A.QUSTNB_TMPT_MNG_NO AND C.SRVY_RSPNS_MNG_NO = B.SRVY_RSPNS_MNG_NO
WHERE A.ROW_NUMBER = 1 ) T4 ON T4.TRPR_INFO_NO = T.TRPR_INFO_NO AND T4.APLY_RCPT_SN = T.APLY_RCPT_SN LEFT JOIN /* 사례종결 */ ( SELECT C.* , A.TRPR_INFO_NO , D.SRVC_EXCN_BIZ_NO , ROW_NUMBER() OVER(PARTITION BY B.CASE_MNG_NO, B.CASE_MNG_ODRNO ORDER BY B.CASE_TRMN_NO DESC) AS ROW_NUMBER FROM SEB100 A /* 사례기본 */ JOIN SEC100 B /* 사례종결 */ ON B.CASE_MNG_NO = A.CASE_MNG_NO AND B.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND B.TRMN_SRNG_RESULT_SE_CD = '02' -- 종결심사결과:승인 JOIN SEC100 C /* 사례종결 */ ON C.CASE_MNG_NO = A.CASE_MNG_NO AND C.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND C.TRMN_SRNG_RESULT_SE_CD = '01' -- 종결심사결과:요청 JOIN SEB120 D /* 서비스사업대상자 */ ON D.CASE_MNG_NO = A.CASE_MNG_NO AND D.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND D.DEL_YN != 'Y' ) T6 ON T6.ROW_NUMBER = 1 AND T6.TRPR_INFO_NO = T.TRPR_INFO_NO AND T6.SRVC_EXCN_BIZ_NO = T.SRVC_EXCN_BIZ_NO JOIN SDA420 T8 /* 서비스실행사업 */ ON T8.SRVC_EXCN_BIZ_NO = T.SRVC_EXCN_BIZ_NO JOIN SDA400 T9 /* 서비스사업 */ ON T9.SRVC_BIZ_NO = T8.SRVC_BIZ_NO
WHERE 1=1
/* 사업연도 */ AND T9.BIZ_YR IN
#{arr}
/* 기관[기관번호] */ AND T.RSFR_INST_NO IN
#{arr}
/* 과정[서비스실행사업번호] */ AND T.SRVC_EXCN_BIZ_NO IN
#{arr}
)
SELECT SE -- 구분 , COUNT(CASE WHEN SXDC_SE_CD = 'M' THEN 1 END) AS SXDC_MALE_NMPR -- 성별-남-인원 , COUNT(CASE WHEN SXDC_SE_CD = 'F' THEN 1 END) AS SXDC_FEMALE_NMPR -- 성별-여-인원 , COUNT(CASE WHEN SXDC_SE_CD = 'M' AND ACBG_SE_CD = '02' THEN 1 END) AS ACBG_ELESCH_MALE -- 교급-초등-남 , COUNT(CASE WHEN SXDC_SE_CD = 'M' AND SCHULW_DSCNTC_ACBG_SE_CD = '02' THEN 1 END) AS ACBG_ELESCH_MALE_SCHULW_DSCNTC -- 교급-초등-남(학업중단) , COUNT(CASE WHEN SXDC_SE_CD = 'F' AND ACBG_SE_CD = '02' THEN 1 END) AS ACBG_ELESCH_FEMALE -- 교급-초등-여 , COUNT(CASE WHEN SXDC_SE_CD = 'F' AND SCHULW_DSCNTC_ACBG_SE_CD = '02' THEN 1 END) AS ACBG_ELESCH_FEMALE_SCHULW_DSCNTC -- 교급-초등-여(학업중단) , COUNT(CASE WHEN SXDC_SE_CD = 'M' AND ACBG_SE_CD = '03' THEN 1 END) AS ACBG_MSKUL_MALE -- 교급-중등-남 , COUNT(CASE WHEN SXDC_SE_CD = 'M' AND SCHULW_DSCNTC_ACBG_SE_CD = '03' THEN 1 END) AS ACBG_MSKUL_MALE_SCHULW_DSCNTC -- 교급-중등-남(학업중단) , COUNT(CASE WHEN SXDC_SE_CD = 'F' AND ACBG_SE_CD = '03' THEN 1 END) AS ACBG_MSKUL_FEMALE -- 교급-중등-여 , COUNT(CASE WHEN SXDC_SE_CD = 'F' AND SCHULW_DSCNTC_ACBG_SE_CD = '03' THEN 1 END) AS ACBG_MSKUL_FEMALE_SCHULW_DSCNTC -- 교급-중등-여(학업중단) , COUNT(CASE WHEN SXDC_SE_CD = 'M' AND ACBG_SE_CD = '04' THEN 1 END) AS ACBG_HGSCHL_MALE -- 교급-고등-남 , COUNT(CASE WHEN SXDC_SE_CD = 'M' AND SCHULW_DSCNTC_ACBG_SE_CD = '04' THEN 1 END) AS ACBG_HGSCHL_MALE_SCHULW_DSCNTC -- 교급-고등-남(학업중단) , COUNT(CASE WHEN SXDC_SE_CD = 'F' AND ACBG_SE_CD = '04' THEN 1 END) AS ACBG_HGSCHL_FEMALE -- 교급-고등-여 , COUNT(CASE WHEN SXDC_SE_CD = 'F' AND SCHULW_DSCNTC_ACBG_SE_CD = '04' THEN 1 END) AS ACBG_HGSCHL_FEMALE_SCHULW_DSCNTC -- 교급-고등-여(학업중단) , COUNT(CASE WHEN ZIP BETWEEN '01' AND '09' THEN 1 END) AS RGN_SEOUL -- 지역-서울 , COUNT(CASE WHEN ZIP BETWEEN '46' AND '49' THEN 1 END) AS RGN_BUSAN -- 지역-부산 , COUNT(CASE WHEN ZIP BETWEEN '41' AND '43' THEN 1 END) AS RGN_DAEGU -- 지역-대구 , COUNT(CASE WHEN ZIP BETWEEN '21' AND '23' THEN 1 END) AS RGN_INCHEON -- 지역-인천 , COUNT(CASE WHEN ZIP BETWEEN '61' AND '62' THEN 1 END) AS RGN_GWANGJU -- 지역-광주 , COUNT(CASE WHEN ZIP BETWEEN '34' AND '35' THEN 1 END) AS RGN_DAEJEON -- 지역-대전 , COUNT(CASE WHEN ZIP BETWEEN '44' AND '45' THEN 1 END) AS RGN_ULSAN -- 지역-울산 , COUNT(CASE WHEN ZIP BETWEEN '30' AND '30' THEN 1 END) AS RGN_SEJONG -- 지역-세종 , COUNT(CASE WHEN ZIP BETWEEN '63' AND '63' THEN 1 END) AS RGN_JEJU -- 지역-제주 , COUNT(CASE WHEN ZIP BETWEEN '10' AND '20' THEN 1 END) AS RGN_GYEONGGI -- 지역-경기 , COUNT(CASE WHEN ZIP BETWEEN '24' AND '26' THEN 1 END) AS RGN_GANGWON -- 지역-강원 , COUNT(CASE WHEN ZIP BETWEEN '27' AND '29' THEN 1 END) AS RGN_CHUNGBUK -- 지역-충북 , COUNT(CASE WHEN ZIP BETWEEN '31' AND '33' THEN 1 END) AS RGN_CHUNGNAM -- 지역-충남 , COUNT(CASE WHEN ZIP BETWEEN '54' AND '56' THEN 1 END) AS RGN_JEONBUK -- 지역-전북 , COUNT(CASE WHEN ZIP BETWEEN '57' AND '60' THEN 1 END) AS RGN_JEONNAM -- 지역-전남 , COUNT(CASE WHEN ZIP BETWEEN '36' AND '40' THEN 1 END) AS RGN_GYEONGBUK -- 지역-경북 , COUNT(CASE WHEN ZIP BETWEEN '50' AND '53' THEN 1 END) AS RGN_GYEONGNAM -- 지역-경남 , COUNT(CASE WHEN PBLAST_SE_CD = '01' THEN 1 END) AS PBLAST_BSIS_LVING_RECIPI -- 공적부조-국민기초생활수급대상 , COUNT(CASE WHEN PBLAST_SE_CD = '02' THEN 1 END) AS PBLAST_LWRFMY -- 공적부조-차상위계층 , COUNT(CASE WHEN PBLAST_SE_CD = '03' THEN 1 END) AS PBLAST_SGLPR -- 공적부조-저소득한부모가족 , COUNT(CASE WHEN PBLAST_SE_CD = '04' THEN 1 END) AS PBLAST_NORLVT -- 공적부조-미해당 , COUNT(CASE WHEN PBLAST_SE_CD = '05' THEN 1 END) AS PBLAST_UNCNFR -- 공적부조-미확인 , COUNT(CASE WHEN PBLAST_SE_CD = '99' THEN 1 END) AS PBLAST_ETC -- 공적부조-기타 , COUNT(CASE WHEN FAM_SHAPE_SE_CD = '01' THEN 1 END) AS FAM_SHAPE_PARNTS -- 가족형태-부모동거 , COUNT(CASE WHEN FAM_SHAPE_SE_CD = '02' THEN 1 END) AS FAM_SHAPE_SGLE -- 가족형태-혼자거주 , COUNT(CASE WHEN FAM_SHAPE_SE_CD = '03' THEN 1 END) AS FAM_SHAPE_BRTHRS -- 가족형태-형제동거 , COUNT(CASE WHEN FAM_SHAPE_SE_CD = '04' THEN 1 END) AS FAM_SHAPE_RELATIVE -- 거족형태-친척동거 , COUNT(CASE WHEN FAM_SHAPE_SE_CD = '05' THEN 1 END) AS FAM_SHAPE_SGLPR -- 거족형태-한부모가족 , COUNT(CASE WHEN FAM_SHAPE_SE_CD = '06' THEN 1 END) AS FAM_SHAPE_GRND_PARNTS -- 가족형태-조손가족 , COUNT(CASE WHEN FAM_SHAPE_SE_CD = '07' THEN 1 END) AS FAM_SHAPE_FCLTY -- 가족형태-시설보호 , COUNT(CASE WHEN FAM_SHAPE_SE_CD = '08' THEN 1 END) AS FAM_SHAPE_CNSGN -- 가족형태-가정위탁 , COUNT(CASE WHEN FAM_SHAPE_SE_CD = '09' THEN 1 END) AS FAM_SHAPE_UNCNFR -- 가족형태-미확인 , COUNT(CASE WHEN FAM_SHAPE_SE_CD = '99' THEN 1 END) AS FAM_SHAPE_ETC -- 가족형태-기타 , COUNT(CASE WHEN DSCSN_CONT > 0 THEN 1 END) AS DSCSN_MDLRT_YN_Y_NOPE -- 상담치료경험여부-있음-인원 , COUNT(CASE WHEN RPRS_MAAP_PROBM_SE_CD = '01' THEN 1 END) AS MAAP_MIND -- 주호소-정신증 , COUNT(CASE WHEN RPRS_MAAP_PROBM_SE_CD = '02' THEN 1 END) AS MAAP_DEPRES -- 주호소-우울증 , COUNT(CASE WHEN RPRS_MAAP_PROBM_SE_CD = '03' THEN 1 END) AS MAAP_FEEL_TROBL -- 주호소-기분장애 , COUNT(CASE WHEN RPRS_MAAP_PROBM_SE_CD = '04' THEN 1 END) AS MAAP_ANXIET -- 주호소-불안 , COUNT(CASE WHEN RPRS_MAAP_PROBM_SE_CD = '05' THEN 1 END) AS MAAP_SMTIZN -- 주호소-신체화 , COUNT(CASE WHEN RPRS_MAAP_PROBM_SE_CD = '07' THEN 1 END) AS MAAP_DPNDNC -- 주호소-의존성 , COUNT(CASE WHEN RPRS_MAAP_PROBM_SE_CD = '06' THEN 1 END) AS MAAP_EAT_TROBL -- 주호소-식이장애 , COUNT(CASE WHEN RPRS_MAAP_PROBM_SE_CD = '14' THEN 1 END) AS MAAP_LRN -- 주호소-학습이해 , COUNT(CASE WHEN RPRS_MAAP_PROBM_SE_CD = '08' THEN 1 END) AS MAAP_ADHD -- 주호소-ADHD , COUNT(CASE WHEN RPRS_MAAP_PROBM_SE_CD = '09' THEN 1 END) AS MAAP_CMPLSN -- 주호소-강박증 , COUNT(CASE WHEN RPRS_MAAP_PROBM_SE_CD = '15' THEN 1 END) AS MAAP_DLINQ -- 주호소-비행 , COUNT(CASE WHEN RPRS_MAAP_PROBM_SE_CD = '10' THEN 1 END) AS MAAP_CNDCT_TROBL -- 주호소-품행장애 , COUNT(CASE WHEN RPRS_MAAP_PROBM_SE_CD = '11' THEN 1 END) AS MAAP_SEX -- 주호소-성 , COUNT(CASE WHEN RPRS_MAAP_PROBM_SE_CD = '16' THEN 1 END) AS MAAP_TWDPSN_REL -- 주호소-대인관계 , COUNT(CASE WHEN RPRS_MAAP_PROBM_SE_CD = '13' THEN 1 END) AS MAAP_VIOLNC_DMGE -- 주호소-폭력(피해) , COUNT(CASE WHEN RPRS_MAAP_PROBM_SE_CD = '12' THEN 1 END) AS MAAP_VIOLNC_DO -- 주호소-폭력(가해) , COUNT(CASE WHEN RPRS_MAAP_PROBM_SE_CD = '99' THEN 1 END) AS MAAP_ETC -- 주호소-기타 , COUNT(CASE WHEN SPCLA_PROBM_DRFSTF = 1 THEN 1 END) AS SPCLA_PROBM_DRFSTF -- 특별문제-약물 , COUNT(CASE WHEN SPCLA_PROBM_DRNKG = 1 THEN 1 END) AS SPCLA_PROBM_DRNKG -- 특별문제-음주 , COUNT(CASE WHEN SPCLA_PROBM_GAMBLE = 1 THEN 1 END) AS SPCLA_PROBM_GAMBLE -- 특별문제-도박 , COUNT(CASE WHEN SPCLA_PROBM_DRFSTF = 0 AND SPCLA_PROBM_DRNKG = 0 AND SPCLA_PROBM_GAMBLE = 0 THEN 1 END) AS SPCLA_PROBM_NONE -- 특별문제-해당없음 , COUNT(CASE WHEN LGSLTN_PRTCTN_OBSERV = 1 THEN 1 END) AS LGSLTN_PRTCTN_OBSERV -- 법률문제-보호관찰 , COUNT(CASE WHEN LGSLTN_TRL = 1 THEN 1 END) AS LGSLTN_TRL -- 법률문제-재판 , COUNT(CASE WHEN LGSLTN_SCHL_VIOLNC = 1 THEN 1 END) AS LGSLTN_SCHL_VIOLNC -- 법률문제-학교폭력 , COUNT(CASE WHEN LGSLTN_POLC_EXMN = 1 THEN 1 END) AS LGSLTN_POLC_EXMN -- 법률문제-경찰조사 , COUNT(CASE WHEN LGSLTN_PRTCTN_OBSERV = 0 AND LGSLTN_TRL = 0 AND LGSLTN_SCHL_VIOLNC = 0 AND LGSLTN_POLC_EXMN = 0 THEN 1 END) AS LGSLTN_NONE -- 법률문제-해당사항없음 , COUNT(CASE WHEN LIVTGT_YN = 5 THEN 1 END) AS LIVTGT_YN_Y -- 동거여부-예 , COUNT(CASE WHEN LIVTGT_YN = 0 THEN 1 END) AS LIVTGT_YN_N -- 동거여부-아니요 , COUNT(CASE WHEN LVING_MNG_YN = 5 THEN 1 END) AS LVING_MNG_YN_Y -- 생활관리여부-예 , COUNT(CASE WHEN LVING_MNG_YN = 0 THEN 1 END) AS LVING_MNG_YN_N -- 생활관리여부-아니요 , COUNT(TRPR_INFO_NO) AS NOPE_SUM -- 인원수합계
FROM ( /* 더미 */ SELECT NULL AS SE -- 구분 , NULL AS OD -- 순서 , NULL AS TRPR_INFO_NO -- 대상자정보번호 , NULL AS APLY_RCPT_SN -- 신청접수일련번호 , NULL AS SXDC_SE_CD -- 성별구분코드 , NULL AS ACBG_SE_CD -- 학력구분코드 , NULL AS SCHULW_DSCNTC_ACBG_SE_CD -- 학업중단학력구분코드 , NULL AS ZIP -- 우편번호(시도) , NULL AS PBLAST_SE_CD -- 공적부조 , NULL AS FAM_SHAPE_SE_CD -- 가족형태구분코드 , NULL AS DSCSN_CONT -- 상담횟수 , NULL AS RPRS_MAAP_PROBM_SE_CD -- 대표주호소구분코드 , NULL AS SPCLA_PROBM_DRFSTF -- 특별문제유형여부 - 약물 , NULL AS SPCLA_PROBM_DRNKG -- 특별문제유형여부 - 음주 , NULL AS SPCLA_PROBM_GAMBLE -- 특별문제유형여부 - 도박 , NULL AS LGSLTN_PRTCTN_OBSERV -- 법률문제 - 보호관찰 , NULL AS LGSLTN_TRL -- 법률문제 - 재판진행 , NULL AS LGSLTN_SCHL_VIOLNC -- 법률문제 - 학교폭력 , NULL AS LGSLTN_POLC_EXMN -- 법률문제 - 경찰조사 , NULL AS LIVTGT_YN -- 동거여부 , NULL AS LVING_MNG_YN -- 생활관리여부 FROM DUAL WHERE 1=2
/* 서류심사-서류선정 */ UNION ALL
