ORDER BY OD

/* selectAplyInstReprts 입교현황통합보고서 신청기관별 조회 - Lee Sanghoon */ WITH TMP000 AS ( SELECT T.TRPR_INFO_NO -- 대상자정보번호 , T.APLY_RCPT_SN -- 신청접수일련번호 , T5.APLY_RCPT_SRNG_SE_CD -- 신청접수심사구분코드 , T5.APLY_RCPT_SRNG_PRGRS_STTS_SE_CD -- 신청접수심사진행상태구분코드 , T.RCPT_RQST_COURS_SE_CD -- 의뢰접수경로구분코드 , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'RCPT_RQST_COURS_SE_CD' AND CMMNS_CD_VALUE = T.RCPT_RQST_COURS_SE_CD) AS APLY_INST -- 신청기관[접수의뢰경로] , T6.TRMN_SE_CD -- 종결구분코드 , T6.TRMN_CS_SE_CD -- 종결사유구분코드
FROM AFA100 T /* 신청접수 */ JOIN SEA200 T1 /* 대상자정보 */ ON T1.TRPR_INFO_NO = T.TRPR_INFO_NO JOIN AFA150 T5 /* 신청접수심사상태정보이력 */ ON T5.TRPR_INFO_NO = T.TRPR_INFO_NO AND T5.APLY_RCPT_SN = T.APLY_RCPT_SN LEFT JOIN /* 사례종결 */ ( SELECT C.* , A.TRPR_INFO_NO , D.SRVC_EXCN_BIZ_NO , ROW_NUMBER() OVER(PARTITION BY B.CASE_MNG_NO, B.CASE_MNG_ODRNO ORDER BY B.CASE_TRMN_NO DESC) AS ROW_NUMBER FROM SEB100 A /* 사례기본 */ JOIN SEC100 B /* 사례종결 */ ON B.CASE_MNG_NO = A.CASE_MNG_NO AND B.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND B.TRMN_SRNG_RESULT_SE_CD = '02' -- 종결심사결과:승인 JOIN SEC100 C /* 사례종결 */ ON C.CASE_MNG_NO = A.CASE_MNG_NO AND C.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND C.TRMN_SRNG_RESULT_SE_CD = '01' -- 종결심사결과:신청 JOIN SEB120 D /* 서비스사업대상자 */ ON D.CASE_MNG_NO = A.CASE_MNG_NO AND D.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND D.DEL_YN != 'Y' ) T6 ON T6.ROW_NUMBER = 1 AND T6.TRPR_INFO_NO = T.TRPR_INFO_NO AND T6.SRVC_EXCN_BIZ_NO = T.SRVC_EXCN_BIZ_NO JOIN SDA420 T8 /* 서비스실행사업 */ ON T8.SRVC_EXCN_BIZ_NO = T.SRVC_EXCN_BIZ_NO JOIN SDA400 T9 /* 서비스사업 */ ON T9.SRVC_BIZ_NO = T8.SRVC_BIZ_NO
WHERE 1=1 AND SUBSTR(T.RCPT_RQST_COURS_SE_CD,0,2) <> '01'
/* 사업연도 */ AND T9.BIZ_YR IN
#{arr}
/* 기관[기관번호] */ AND T.RSFR_INST_NO IN
#{arr}
/* 과정[서비스실행사업번호] */ AND T.SRVC_EXCN_BIZ_NO IN
#{arr}
)
SELECT SE -- 구분 , NVL(APLY_INST,'-') AS APLY_INST -- 신청기관 , COUNT(TRPR_INFO_NO) AS NMPR -- 인원
FROM ( /* 더미 */ SELECT NULL AS SE -- 구분 , NULL AS APLY_INST -- 신청기관 , NULL AS OD -- 순서 , NULL AS TRPR_INFO_NO -- 대상자정보번호 , NULL AS APLY_RCPT_SN -- 신청접수일련번호 FROM DUAL WHERE 1=2
/* 서류심사-서류선정 */ UNION ALL
SELECT DISTINCT SE -- 구분 , APLY_INST -- 신청기관 , OD1 || RCPT_RQST_COURS_SE_CD AS OD -- 순서 , TRPR_INFO_NO -- 대상자정보번호 , APLY_RCPT_SN -- 신청접수일련번호 FROM ( SELECT '서류심사-서류선정' AS SE , 11 AS OD1 FROM DUAL ) LEFT JOIN TMP000 ON APLY_RCPT_SRNG_PRGRS_STTS_SE_CD IN ('0203','0401') -- 신청접수심사진행상태:신청검토-선정, 접수-승인 AND (TRPR_INFO_NO, APLY_RCPT_SN) NOT IN ( SELECT TRPR_INFO_NO , APLY_RCPT_SN FROM AFA150 WHERE APLY_RCPT_SRNG_PRGRS_STTS_SE_CD IN ('0402','0303') -- 신청접수심사진행상태:접수-미승인, 2단계신청-접수포기 )
/* 서류심사-서류미선정 */ UNION ALL
SELECT DISTINCT SE -- 구분 , APLY_INST -- 신청기관 , OD1 || RCPT_RQST_COURS_SE_CD AS OD -- 순서 , TRPR_INFO_NO -- 대상자정보번호 , APLY_RCPT_SN -- 신청접수일련번호 FROM ( SELECT '서류심사-서류미선정' AS SE , 12 AS OD1 FROM DUAL ) LEFT JOIN TMP000 ON APLY_RCPT_SRNG_PRGRS_STTS_SE_CD IN ('0202','0402') -- 신청접수심사진행상태:신청검토-미선정, 접수-미승인
/* 서류심사-접수포기 */ UNION ALL
SELECT DISTINCT SE -- 구분 , APLY_INST -- 신청기관 , OD1 || RCPT_RQST_COURS_SE_CD AS OD -- 순서 , TRPR_INFO_NO -- 대상자정보번호 , APLY_RCPT_SN -- 신청접수일련번호 FROM ( SELECT '서류심사-접수포기' AS SE , 13 AS OD1 FROM DUAL ) LEFT JOIN TMP000 ON APLY_RCPT_SRNG_PRGRS_STTS_SE_CD IN ('0303') -- 신청접수심사진행상태:2단계신청-접수포기
/* 서류심사-반송 */ UNION ALL
SELECT DISTINCT SE -- 구분 , APLY_INST -- 신청기관 , OD1 || RCPT_RQST_COURS_SE_CD AS OD -- 순서 , TRPR_INFO_NO -- 대상자정보번호 , APLY_RCPT_SN -- 신청접수일련번호 FROM ( SELECT '서류심사-반송' AS SE , 14 AS OD1 FROM DUAL ) LEFT JOIN TMP000 ON APLY_RCPT_SRNG_PRGRS_STTS_SE_CD IN ('0201') -- 신청접수심사진행상태:신청검토-반송
/* 면접심사-선정 */ UNION ALL
SELECT DISTINCT SE -- 구분 , APLY_INST -- 신청기관 , OD1 || RCPT_RQST_COURS_SE_CD AS OD -- 순서 , TRPR_INFO_NO -- 대상자정보번호 , APLY_RCPT_SN -- 신청접수일련번호 FROM ( SELECT '면접심사-선정' AS SE , 21 AS OD1 FROM DUAL ) LEFT JOIN TMP000 ON APLY_RCPT_SRNG_PRGRS_STTS_SE_CD IN ('0504') -- 신청접수심사진행상태:심사(면접)-선정
/* 면접심사-심사중 */ UNION ALL
SELECT DISTINCT SE -- 구분 , APLY_INST -- 신청기관 , OD1 || RCPT_RQST_COURS_SE_CD AS OD -- 순서 , TRPR_INFO_NO -- 대상자정보번호 , APLY_RCPT_SN -- 신청접수일련번호 FROM ( SELECT '면접심사-심사중' AS SE , 22 AS OD1 FROM DUAL ) LEFT JOIN TMP000 ON APLY_RCPT_SRNG_PRGRS_STTS_SE_CD IN ('0503') -- 신청접수심사진행상태:심사(면접)-심사중
/* 면접심사-보류 */ UNION ALL
SELECT DISTINCT SE -- 구분 , APLY_INST -- 신청기관 , OD1 || RCPT_RQST_COURS_SE_CD AS OD -- 순서 , TRPR_INFO_NO -- 대상자정보번호 , APLY_RCPT_SN -- 신청접수일련번호 FROM ( SELECT '면접심사-보류' AS SE , 23 AS OD1 FROM DUAL ) LEFT JOIN TMP000 ON APLY_RCPT_SRNG_PRGRS_STTS_SE_CD IN ('0505') -- 신청접수심사진행상태:심사(면접)-보류
/* 면접심사-미선정 */ UNION ALL
SELECT DISTINCT SE -- 구분 , APLY_INST -- 신청기관 , OD1 || RCPT_RQST_COURS_SE_CD AS OD -- 순서 , TRPR_INFO_NO -- 대상자정보번호 , APLY_RCPT_SN -- 신청접수일련번호 FROM ( SELECT '면접심사-미선정' AS SE , 24 AS OD1 FROM DUAL ) LEFT JOIN TMP000 ON APLY_RCPT_SRNG_PRGRS_STTS_SE_CD IN ('0502') -- 신청접수심사진행상태:심사(면접)-미선정
/* 면접심사-심사포기 */ UNION ALL
SELECT DISTINCT SE -- 구분 , APLY_INST -- 신청기관 , OD1 || RCPT_RQST_COURS_SE_CD AS OD -- 순서 , TRPR_INFO_NO -- 대상자정보번호 , APLY_RCPT_SN -- 신청접수일련번호 FROM ( SELECT '면접심사-심사포기' AS SE , 25 AS OD1 FROM DUAL ) LEFT JOIN TMP000 ON APLY_RCPT_SRNG_PRGRS_STTS_SE_CD IN ('0501') -- 신청접수심사진행상태:심사(면접)-심사포기
/* 최종입교-최종입교 */ UNION ALL
SELECT DISTINCT SE -- 구분 , APLY_INST -- 신청기관 , OD1 || RCPT_RQST_COURS_SE_CD AS OD -- 순서 , TRPR_INFO_NO -- 대상자정보번호 , APLY_RCPT_SN -- 신청접수일련번호 FROM ( SELECT '최종입교-최종입교' AS SE , 31 AS OD1 FROM DUAL ) LEFT JOIN TMP000 ON APLY_RCPT_SRNG_PRGRS_STTS_SE_CD IN ('0604') -- 신청접수심사진행상태:최종-선정 AND (TRMN_SE_CD NOT IN ('11') OR TRMN_SE_CD IS NULL) -- 종결구분:적응기간퇴교
/* 최종입교-적응기간 입교생 */ UNION ALL
SELECT DISTINCT SE -- 구분 , APLY_INST -- 신청기관 , OD1 || RCPT_RQST_COURS_SE_CD AS OD -- 순서 , TRPR_INFO_NO -- 대상자정보번호 , APLY_RCPT_SN -- 신청접수일련번호 FROM ( SELECT '최종입교-적응기간 입교생' AS SE , 32 AS OD1 FROM DUAL ) LEFT JOIN TMP000 ON APLY_RCPT_SRNG_PRGRS_STTS_SE_CD IN ('0605') -- 신청접수심사진행상태:최종-선정(대체)
/* 최종입교-예비후보자 */ UNION ALL
SELECT DISTINCT SE -- 구분 , APLY_INST -- 신청기관 , OD1 || RCPT_RQST_COURS_SE_CD AS OD -- 순서 , TRPR_INFO_NO -- 대상자정보번호 , APLY_RCPT_SN -- 신청접수일련번호 FROM ( SELECT '최종입교-예비후보자' AS SE , 33 AS OD1 FROM DUAL ) LEFT JOIN TMP000 ON APLY_RCPT_SRNG_PRGRS_STTS_SE_CD IN ('0603') -- 신청접수심사진행상태:최종-예비후보자
/* 최종입교-결정보류 */ UNION ALL
SELECT DISTINCT SE -- 구분 , APLY_INST -- 신청기관 , OD1 || RCPT_RQST_COURS_SE_CD AS OD -- 순서 , TRPR_INFO_NO -- 대상자정보번호 , APLY_RCPT_SN -- 신청접수일련번호 FROM ( SELECT '최종입교-결정보류' AS SE , 34 AS OD1 FROM DUAL ) LEFT JOIN TMP000 ON APLY_RCPT_SRNG_PRGRS_STTS_SE_CD IN ('0602') -- 신청접수심사진행상태:최종-결정보류
/* 최종입교-최종미선정 */ UNION ALL
SELECT DISTINCT SE -- 구분 , APLY_INST -- 신청기관 , OD1 || RCPT_RQST_COURS_SE_CD AS OD -- 순서 , TRPR_INFO_NO -- 대상자정보번호 , APLY_RCPT_SN -- 신청접수일련번호 FROM ( SELECT '최종입교-최종미선정' AS SE , 35 AS OD1 FROM DUAL ) LEFT JOIN TMP000 ON APLY_RCPT_SRNG_PRGRS_STTS_SE_CD IN ('0601') -- 신청접수심사진행상태:최종-미선정
/* 최종입교-입교포기(적응기간) */ UNION ALL
SELECT DISTINCT SE -- 구분 , APLY_INST -- 신청기관 , OD1 || RCPT_RQST_COURS_SE_CD AS OD -- 순서 , TRPR_INFO_NO -- 대상자정보번호 , APLY_RCPT_SN -- 신청접수일련번호 FROM ( SELECT '최종입교-입교포기(적응기간)' AS SE , 36 AS OD1 FROM DUAL ) LEFT JOIN TMP000 ON APLY_RCPT_SRNG_PRGRS_STTS_SE_CD IN ('0604') -- 신청접수심사진행상태:최종-선정 AND TRMN_SE_CD IN ('11') -- 종결구분:적응기간퇴교
/* 수료-일반수료 */ UNION ALL
SELECT DISTINCT SE -- 구분 , APLY_INST -- 신청기관 , OD1 || RCPT_RQST_COURS_SE_CD AS OD -- 순서 , TRPR_INFO_NO -- 대상자정보번호 , APLY_RCPT_SN -- 신청접수일련번호 FROM ( SELECT '수료-일반수료' AS SE , 41 AS OD1 FROM DUAL ) LEFT JOIN TMP000 ON TRMN_SE_CD IN ('01') -- 종결구분:수료
/* 수료-조기수료 */ UNION ALL
SELECT DISTINCT SE -- 구분 , APLY_INST -- 신청기관 , OD1 || RCPT_RQST_COURS_SE_CD AS OD -- 순서 , TRPR_INFO_NO -- 대상자정보번호 , APLY_RCPT_SN -- 신청접수일련번호 FROM ( SELECT '수료-조기수료' AS SE , 42 AS OD1 FROM DUAL ) LEFT JOIN TMP000 ON TRMN_SE_CD IN ('02') -- 종결구분:조기수료
/* 수료-기관퇴교 */ UNION ALL
SELECT DISTINCT SE -- 구분 , APLY_INST -- 신청기관 , OD1 || RCPT_RQST_COURS_SE_CD AS OD -- 순서 , TRPR_INFO_NO -- 대상자정보번호 , APLY_RCPT_SN -- 신청접수일련번호 FROM ( SELECT '수료-기관퇴교' AS SE , 43 AS OD1 FROM DUAL ) LEFT JOIN TMP000 ON TRMN_SE_CD IN ('04') -- 종결구분:중도탈락 AND TRMN_CS_SE_CD IN ('063') -- 종결사유:기관퇴교
/* 수료-자의퇴교 */ UNION ALL
SELECT DISTINCT SE -- 구분 , APLY_INST -- 신청기관 , OD1 || RCPT_RQST_COURS_SE_CD AS OD -- 순서 , TRPR_INFO_NO -- 대상자정보번호 , APLY_RCPT_SN -- 신청접수일련번호 FROM ( SELECT '수료-자의퇴교' AS SE , 44 AS OD1 FROM DUAL ) LEFT JOIN TMP000 ON TRMN_SE_CD IN ('04') -- 종결구분:중도탈락 AND TRMN_CS_SE_CD IN ('062') -- 종결사유:자의퇴교
)
GROUP BY SE, APLY_INST, OD
ORDER BY OD
